function validate([chalk, k]) {
  if (!Array.isArray(chalk) || chalk.length < 1 || chalk.length > 100000) return 'chalk needs 1 to 100000 values.';
  if (chalk.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each chalk[i] is an integer from 1 to 100000.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is an integer from 1 to 10^9.';
  return null;
}

