function chalkReplacer(chalk, k) {
  const n = chalk.length;
  const prefix = new Array(n);
  prefix[0] = chalk[0];
  for (let i = 1; i < n; i++) {
    prefix[i] = prefix[i - 1] + chalk[i];
  }
  const remaining = k % prefix[n - 1];

  let left = 0;
  let right = n - 1;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (prefix[mid] > remaining) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

