function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const high = size === 'large' || rand() < 0.3 ? 100000 : 10;
  const chalk = Array.from({ length: n }, () => 1 + Math.floor(rand() * high));
  const total = chalk.reduce((a, b) => a + b, 0);
  const pick = rand();
  let k;
  if (pick < 0.4) k = 1 + Math.floor(rand() * 1e9);
  else if (pick < 0.7) k = 1 + Math.floor(rand() * Math.min(1e9, 3 * total));
  else k = Math.max(1, Math.min(1e9, total * (1 + Math.floor(rand() * 3)) - Math.floor(rand() * 2)));
  return [chalk, k];
}
